/* ---------- Reactions ---------- */
/* an agent message in the feed: no container; with .panel it becomes a card */
.rxx{padding:14px 0;display:flex;flex-direction:column;gap:10px}
.rxx.panel{padding:14px}
.rxx-m{display:flex;gap:10px}
.rxx-ic{width:30px;height:30px;border-radius:10px;background:var(--accent);color:var(--on-accent);display:grid;place-items:center;flex:none}
.rxx-b{display:flex;flex-direction:column;font-size:13.5px;line-height:1.5;min-width:0}
.rxx-n{display:flex;gap:6px;align-items:baseline;font-size:13px}
.rxx-n b{font-weight:500}
.rxx-n .muted{font-size:11.5px}
.rxx-b p{margin:2px 0 0;color:var(--fg2)}
.rxx-row{display:flex;flex-wrap:wrap;gap:5px;padding-left:40px;align-items:center}
.rxx-list{display:contents}
.rxx-r{position:relative;display:inline-flex;align-items:center;gap:5px;height:28px;padding:0 9px;border-radius:999px;background:var(--chip);font-size:13px;transition:background .2s,box-shadow .2s,transform .15s,opacity .3s}
@media (hover:hover) and (pointer:fine){.rxx-r:hover{background:var(--hover)}}
.rxx-r:active{transform:scale(.94)}
.rxx-r.me{background:var(--sel);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent-mark,var(--accent)) 40%,transparent)}
.rxx-r .n{display:inline-grid;overflow:hidden;height:16px;font-size:12px;line-height:16px;color:var(--fg2);min-width:8px}
.rxx-r .n i{grid-area:1/1;font-style:normal;text-align:center}
.rxx-r.me .n{color:var(--accent-fg,var(--accent));font-weight:500}
.rxx-r .n .iu{animation:rxiu .38s var(--ease) both}.rxx-r .n .ou{animation:rxou .38s var(--ease) both}
.rxx-r .n .id{animation:rxid .38s var(--ease) both}.rxx-r .n .od{animation:rxod .38s var(--ease) both}
@keyframes rxiu{from{transform:translateY(100%);opacity:0}}@keyframes rxou{to{transform:translateY(-100%);opacity:0}}
@keyframes rxid{from{transform:translateY(-100%);opacity:0}}@keyframes rxod{to{transform:translateY(100%);opacity:0}}
.rxx-r::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;opacity:0}
.rxx-r.bump::after{animation:rxring .6s var(--ease)}
@keyframes rxring{0%{opacity:.5;box-shadow:0 0 0 0 var(--accent-mark,var(--accent))}100%{opacity:0;box-shadow:0 0 0 7px var(--accent-mark,var(--accent))}}
.rxx-r.new{animation:popin .45s var(--ease) backwards}
.rxx-r.gone{opacity:0;transform:scale(.8)}
.rxx-r .e{display:inline-block}
.rxx-r.bump .e{animation:rxp .5s var(--ease)}
@keyframes rxp{0%{transform:scale(1)}35%{transform:scale(1.5) rotate(-12deg)}60%{transform:scale(.92) rotate(4deg)}100%{transform:scale(1)}}
.rxx-add{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;color:var(--muted);transition:background .2s,color .2s}
.rxx-add[aria-expanded="true"]{background:var(--chip);color:var(--fg)}
@media (hover:hover) and (pointer:fine){.rxx-add:hover{background:var(--chip);color:var(--fg)}}
.rxx-pk{min-width:0;padding:6px}
.rxx-grid{display:grid;grid-template-columns:repeat(6,32px);gap:2px}
.rxx-grid button{width:32px;height:32px;border-radius:8px;font-size:17px;transition:background .15s,transform .2s var(--ease)}
@media (hover:hover) and (pointer:fine){.rxx-grid button:hover{background:var(--chip);transform:scale(1.15)}}

DM.def('reactions', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{spark}', I('spark','xs')).replace('{smile}', I('smile','xs'));
  const R = [['🚀',4,['Maya','Jon','Ari','Sam'],0],['👀',2,['Jon','Dana'],0],['✅',1,['Maya'],0]];
  const list = $('.rxx-list', r);
  const tipOf = b => { const x = b._x, who = x[3] ? ['You', ...x[2]] : x[2]; b.dataset.tip = who.slice(0, 3).join(', ') + (who.length > 3 ? ' and ' + (who.length - 3) + ' more' : ''); if (tipFor === b) showTip(b); };
  function make(x){ const b = html(`<button class="rxx-r${x[3] ? ' me' : ''}" aria-pressed="${!!x[3]}"><span class="e">${x[0]}</span><span class="n num"><i>${x[1]}</i></span></button>`); b._x = x; tipOf(b); b.onclick = () => toggle(b); return b; }
  /* the count rolls up or down instead of the whole row re-rendering under the pointer */
  function roll(b, up){ const n = $('.n', b), old = $('i:last-child', n), nu = html(`<i class="${up ? 'iu' : 'id'}">${b._x[1]}</i>`); old.className = up ? 'ou' : 'od'; n.appendChild(nu); setTimeout(() => old.remove(), 380); }
  function bump(b){ b.classList.remove('bump'); void b.offsetWidth; b.classList.add('bump'); }
  function toggle(b){ const x = b._x; x[3] = x[3] ? 0 : 1; x[1] += x[3] ? 1 : -1; b.classList.toggle('me', !!x[3]); b.setAttribute('aria-pressed', !!x[3]);
    if (x[1] <= 0){ R.splice(R.indexOf(x), 1); b.classList.add('gone'); hideTip(); setTimeout(() => b.remove(), 320); return; }
    roll(b, !!x[3]); tipOf(b); if (x[3]) bump(b); }
  R.forEach(x => list.appendChild(make(x)));
  $('.rxx-grid', r).innerHTML = ['👍','❤️','🎉','🚀','👀','✅','🔥','💯','🙌','🤔','✨','👏'].map(e => `<button data-close>${e}</button>`).join('');
  $$('.rxx-grid button', r).forEach(b => b.addEventListener('click', () => { const e = b.textContent, x = R.find(y => y[0] === e);
    if (x){ const el = $$('.rxx-r', list).find(y => y._x === x); if (!x[3]) toggle(el); else bump(el); }
    else { const nx = [e, 1, [], 1]; R.push(nx); const el = make(nx); el.classList.add('new'); list.appendChild(el); bump(el); } }));
  // the preview adds one reaction on its own, unless you take over first
  c.auto(1100, () => toggle($('.rxx-r', list)));
});
